import{z as A,x as o,o as E,c as n,q as s,j as B,D as e,d as t,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"构建系统：make 到 bazel","description":"","frontmatter":{"title":"构建系统：make 到 bazel","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/swe-build-systems.md","filePath":"cs/swe-build-systems.md","lastUpdated":1791063341000}'),m={name:"cs/swe-build-systems.md"};function d(p,a,c,C,h,_){const l=o("Mermaid");return E(),n("div",null,[a[2]||(a[2]=s('<h1 id="构建系统-make-到-bazel" tabindex="-1">构建系统：make 到 bazel <a class="header-anchor" href="#构建系统-make-到-bazel" aria-label="Permalink to &quot;构建系统：make 到 bazel&quot;">​</a></h1><div class="epigraph"><p>增量构建的全部正确性押在一个判据上——这件产物还新鲜吗；时间戳是猜测，内容哈希是事实。</p><footer>—— 据 GNU Make 手册与 Bazel 的密封性、缓存文档口径整理</footer></div><p><a href="/cs/swe-branching-changes">上一课</a>把变更收进主干，主干上每一份快照都要能变成可发布的产物。程序设计课的<a href="/cs/build-system">构建系统</a>已经写过 make 的目标、依赖与配方；本课沿工程纵深重走一遍：make 的时间戳增量为什么在大团队失效，bazel 的内容寻址动作图怎么补，密封性为什么是这一切的前提。后课的 CI 默认你已经会动作图与缓存键。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>make 的判据是「目标比依赖旧就重建」，它有三个失效口。时间戳本身不可靠：检出与克隆不保序、文件系统粒度粗、时钟会跳。依赖图靠人写：写漏一条边就漏重建，写全又手工爆炸——<a href="/cs/c-preprocessor">C 预处理器</a>课写过翻译阶段把包含展开，头文件因此都算依赖，机器算得比人准。更根本的是非密封：编译器版本、系统头文件、环境变量都悄悄进结果，「在我机器上能过」没有工程意义。三个口合起来的日常就是：增量结果不可信，于是人人 clean build，增量白做。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把构建声明成动作图：目标为点、动作为边的有向无环图，系统做拓扑排序，无依赖关系的动作并行。bazel 给每个动作定义封闭的键：输入内容摘要、命令行、工具与环境都在键里。键相同就直接取缓存产物，本地缓存与远端缓存共享，跨人跨机一致——「同一主干快照，得到同一产物」。密封性是前提：工具链版本钉死，sysroot 口径见<a href="/cs/cross-compile-triple">交叉编译与三元组</a>；依赖版本锁定；动作在沙箱里执行，主机的环境变量与全局目录进不了结果。</p><p><span class="marginnote">数字实例看增量值多少钱：一个中型仓库全量构建 40 分钟、可信增量 30 秒。判据不可信时人人 clean build，百人团队每天几十次构建，浪费的就是按小时计的机器与人等——增量正确性是工程问题，不是小优化。</span></p>',8)),(E(),B(i,null,{default:e(()=>[r(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22app%20%E4%BA%8C%E8%BF%9B%E5%88%B6%22%5D%20--%3E%20LIB%5B%22lib.a%20%E5%BD%92%E6%A1%A3%22%5D%0A%20%20LIB%20--%3E%20ACT%5B%22%E7%BC%96%E8%AF%91%E5%8A%A8%E4%BD%9C%EF%BC%9A%E8%BE%93%E5%85%A5%E6%91%98%E8%A6%81%20%2B%20%E5%91%BD%E4%BB%A4%20%2B%20%E5%B7%A5%E5%85%B7%22%5D%0A%20%20ACT%20--%3E%20SRC%5B%22a.c%20%E4%B8%8E%E5%A4%B4%E6%96%87%E4%BB%B6%22%5D%0A%20%20ACT%20--%3E%20HIT%7B%22%E7%BC%93%E5%AD%98%E6%9C%89%E6%AD%A4%E9%94%AE%3F%22%7D%0A%20%20HIT%20--%3E%7C%E6%98%AF%7C%20CACHE%5B%22%E5%8F%96%E7%BC%93%E5%AD%98%E4%BA%A7%E7%89%A9%22%5D%0A%20%20HIT%20--%3E%7C%E5%90%A6%7C%20RUN%5B%22%E6%B2%99%E7%AE%B1%E6%89%A7%E8%A1%8C%E5%B9%B6%E5%9B%9E%E5%A1%AB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>判据升级的本质，是从偏序启发式走到精确判据。mtime 比较错了，结果错且无声；内容摘要不会错——输入没变就是没变，变了哈希必变。CI 因此可以信任构建产物：键相同即产物相同，<a href="/cs/swe-git-internals">git 的内部模型</a>里「哈希即校验」的思路在产物侧重演一遍。把「同源同产物」推到字节级一致，就是可复现构建，配套的物料清单见<a href="/cs/sbom-reproducible-builds">SBOM 与可复现构建</a>。</p><p><span class="marginnote">术语翻译：密封性（hermeticity）就是「构建动作能看到的每一份输入都被显式钉住」——源码、依赖版本、工具链全在图里，动作跑在沙箱中；主机上恰好装了什么编译器、设了什么环境变量，都影响不了结果。</span></p><p>make 每一步「重建还是跳过」的判定本身值得画出来。</p>',4)),(E(),B(i,null,{default:e(()=>[r(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%7B%22%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%E5%AD%98%E5%9C%A8%E5%90%97%22%7D%20--%20%22%E5%90%A6%22%20--%3E%20RUN%5B%22%E6%89%A7%E8%A1%8C%E9%85%8D%E6%96%B9%E7%94%9F%E6%88%90%22%5D%0A%20%20T%20--%20%22%E6%98%AF%22%20--%3E%20M%7B%22%E7%9B%AE%E6%A0%87%20mtime%20%E6%AF%94%E6%AF%8F%E4%B8%AA%E4%BE%9D%E8%B5%96%E6%96%B0%E5%90%97%22%7D%0A%20%20M%20--%20%22%E6%9C%89%E4%BE%9D%E8%B5%96%E6%9B%B4%E6%96%B0%22%20--%3E%20RUN%0A%20%20M%20--%20%22%E9%83%BD%E6%9B%B4%E6%97%A7%EF%BC%88%E6%96%B0%E9%B2%9C%EF%BC%89%22%20--%3E%20SKIP%5B%22%E8%B7%B3%E8%BF%87%EF%BC%8C%E8%AE%A4%E4%B8%BA%E4%BA%A7%E7%89%A9%E6%9C%89%E6%95%88%22%5D%0A%20%20RUN%20--%3E%20EDGE%5B%22%E5%89%8D%E6%8F%90%EF%BC%9A%E4%BE%9D%E8%B5%96%E5%9B%BE%E6%B2%A1%E5%86%99%E6%BC%8F%E8%BE%B9%22%5D%0A%20%20SKIP%20--%3E%20EDGE%0A%20%20EDGE%20--%20%22%E6%BC%8F%E8%BE%B9%20%3D%20%E6%BC%8F%E9%87%8D%E5%BB%BA%22%20--%3E%20WARN%5B%22%E4%BA%A7%E7%89%A9%E9%94%99%E4%B8%94%E6%97%A0%E5%A3%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p><span class="marginnote">初学者容易以为增量判据写错顶多「多编译几遍、慢一点」。实际反过来：漏写一条依赖边是<strong>少</strong>重建——旧目标文件被链接进产物，程序带着旧逻辑照常跑，错误无声。bazel 的内容键就是把这个「错且无声」变成「定义上不存在」。</span></p><p><span class="marginnote">亚秒粒度的具体错法：同一秒内先更新头文件再更新源文件，mtime 相等，make 认为 .o 仍然新鲜——经典的「偶发不改」。动作键里没有时间、只有内容摘要，这类问题在定义上消失，而不是被修好。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>bazel 有成本：规则要学、外部依赖要进图、分析期有开销，小项目全是负担；make 不会死——小项目、胶水流程、单目录工具链，它仍是最短路径。生成代码会让依赖图出现「产物又是另一个目标输入」的环，切环技巧与各语言规则生态不展开。构建可复现不等于程序无副作用：运行时行为归测试与交付管。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>make 以时间戳判新旧，bazel 以内容摘要判同一；判据错了，增量就错。</li><li>动作图加封闭键，使产物可缓存、可共享、跨机一致。</li><li>密封性是缓存的前提：工具链钉死、依赖锁定、沙箱执行。</li><li>头文件等隐藏依赖应进图；漏边是漏重建的根源。</li><li>小项目用 make，多语言大库上 bazel；选择随规模不随时髦。</li><li>出处：GNU Make 手册；Bazel 文档（密封性与远端缓存口径）；交叉编译见<a href="/cs/cross-compile-triple">交叉编译与三元组</a>。</li></ul>',6))])}const u=A(m,[["render",d]]);export{b as __pageData,u as default};
